export const mvCoverage=mvParties.map((_,j)=>mvQuestions.filter(q=>q.positions[j]!==null).length);
export function rankMV(answers){return mvParties.map((_,party)=>{let total=0,count=0;mvQuestions.forEach((q,i)=>{const a=answers[i],p=q.positions[party];if(![-1,1].includes(a)||p===null)return;total+=1-Math.abs(a-p)/2;count++});return {party,score:count?Math.round(total/count*100):null,count};}).sort((a,b)=>(b.score??-1)-(a.score??-1)||a.party-b.party);}
